from decimal import Decimal


def _numeric_value(value):
    """Apply the legacy empty-value numeric coercion used by the approve guard."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _account_credit_hold(record, tables):
    """Return the first live matching account's CRED_HOLD value."""
    accounts = tables.get("ACCT_MASTER", [])
    account_id = record.get("ACCT_ID", "")

    for row in accounts:
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    record_copy = dict(record)

    transitions = (
        ("E", "approve"),
        ("A", "ship"),
        ("S", "invoice"),
        ("E", "cancel"),
        ("A", "cancel"),
        ("I", "cancel"),
    )

    matched_transition = None
    for transition in transitions:
        from_state, transition_event = transition
        if state != from_state or event != transition_event:
            continue

        if transition == ("E", "approve"):
            if not (_numeric_value(record.get("TOT_AMT", "")) > 0):
                continue
            matched_transition = ("A", ["ORD_APPR"], [])
            break

        if transition == ("A", "ship"):
            matched_transition = ("S", ["ORD_SHIP"], ["shipped"])
            break

        if transition == ("S", "invoice"):
            matched_transition = ("I", ["ORD_INV"], [])
            break

        if transition == ("E", "cancel"):
            matched_transition = ("X", ["ORD_CANC"], [])
            break

        if transition == ("A", "cancel"):
            if _account_credit_hold(record, tables) == "Y":
                continue
            matched_transition = ("X", ["ORD_CANC"], [])
            break

        if transition == ("I", "cancel"):
            matched_transition = ("X", ["ORD_CANC_INV"], ["credit_note"])
            break

    if matched_transition is None:
        return {
            "state": state,
            "record": record_copy,
            "audits": ["WF_NOMATCH"],
            "notifies": [],
            "matched": False,
        }

    next_state, audits, notifies = matched_transition
    return {
        "state": next_state,
        "record": record_copy,
        "audits": audits,
        "notifies": notifies,
        "matched": True,
    }
